async function ensureObject(id){if(!id)return null;if(objectCards.has(id))return objectCards.get(id);if(!objectJobs.has(id))objectJobs.set(id,(async()=>{const card=await objectStore.card(id);const resources=await objectStore.resources(id);if(card.kind==='fund'){if((card.name+' '+card.type).includes('联接'))card.referencedTarget=await objectStore.target(card.code);const [relation,observations,dailyFactors,extra]=await Promise.all([objectStore.relations(card.code),objectStore.observations(card.code),objectStore.factors(card.code).catch(()=>null),get('data/v13/funds/'+objectShard(card.code)+'.json',{funds:{}})]);card.holdingExtra=extra.funds[card.code];card.dailyFactors=dailyFactors;for(const r of resources)if(r.navObservation){r.navObservation=observations;r.period=observations?.snapshot?.date||r.period;}let f=D.funds.find(f=>f.code===card.code);if(!f){f={id:card.id,code:card.code,name:card.name,type:card.type,holdings:[],disclosure:null};D.funds.push(f);}Object.assign(f,{profile:card,observations,manager:card.managerCompany,indexName:card.trackingIndex?.name},relation||{});}else{const i=D.stocks.findIndex(x=>x.code===card.code);if(i<0)D.stocks.push(card);else D.stocks[i]={...D.stocks[i],...card};}objectCards.set(id,card);objectResources.set(id,resources);return card;})().finally(()=>objectJobs.delete(id)));return objectJobs.get(id);}
async function loadActivity(id){if(!id)return;const {kind,code}=objectIdentity(id),path=`v10/activity/${kind}s/${objectShard(code)}.json`;if(!activityFiles.has(path))activityFiles.set(path,(async()=>loadPublicData(path,await get('data/'+path,{objects:{}}),{timeout:3000}))());const data=await activityFiles.get(path);const newsPath=`v12/news/${kind}s/${objectShard(code)}.json`;if(!activityFiles.has(newsPath))activityFiles.set(newsPath,(async()=>loadPublicData(newsPath,await get('data/'+newsPath,{objects:{}}),{timeout:3000}))());const latest=await activityFiles.get(newsPath);D.eventUpdatedAt=[D.eventUpdatedAt,latest.lastCheckedAt].filter(Boolean).sort().at(-1);const value=data?.objects?.[id]||{news:[],forum:{}};value.news=[...new Map([...(value.news||[]),...(latest.objects?.[id]?.news||[])].map(x=>[x.id,x])).values()];if(value){objectActivities.set(id,value);D.events=[...new Map([...D.events,...(value.news||[])].map(x=>[x.id,x])).values()];const forum=value.forum||{};for(const key of ['records','metrics','claims']){D.forum[key]=[...(D.forum[key]||[]).filter(x=>x.objectId!==id),...(key==='records'?mergePosts((D.forum.records||[]).filter(x=>x.objectId===id),forum.records||[]):forum[key]||[])];}}}
async function loadObjectStreams(id){if(!id)return;await ensureObject(id).catch(()=>{});const fund=D.funds.find(x=>x.id===id);await Promise.allSettled([id,...(fund?.holdings||[]).map(x=>'stock'+x.code)].map(loadActivity));}
async function loadAccountObjects(){S.accountLoading=true;const results=await Promise.allSettled((S.account.items||[]).map(x=>ensureObject('fund'+x.code)));S.accountLoading=false;if(results.some(x=>x.status==='rejected'))toast('部分基金资料读取失败，请刷新重试');if(['holdings','analysis'].includes(S.view))render();await Promise.allSettled(model().funds.map(f=>loadObjectStreams(f.id)));await Promise.allSettled(model().companies.map(c=>ensureObject(c.id)));if(['holdings','analysis','news','sources','discussion'].includes(S.view))render();}
function allSourceRows(){const notices=D.events.filter(e=>e.kind==='公告').map(e=>({id:'document-'+e.id,title:e.title,entities:(e.entities||[]).map(t=>t.kind+t.code),publisher:e.source,kind:'disclosure',cadence:'news',publishedAt:e.date,url:e.url,contentCoverage:'link-only',summary:''}));return [...new Map([...D.reference.sources,...notices,...[...objectCards.values()].flatMap(profileSources),...[...objectResources.values()].flat()].map(x=>[x.id,x])).values()];}
async function searchObjects(input,prefix,mode){const q=input.value;const kind=mode==='company'?'stock':mode==='fund'?'fund':null;const found=await objectStore.search(q,kind);if(!input.isConnected||input.value!==q)return;if(prefix==='source')D.sourceOptions=found;else if(prefix==='timeline')D.timelineOptions[mode]=found;else D.discussionOptions[mode]=found;const select=document.querySelector(prefix==='source'?'#source-object':`[data-${prefix}-object]`);const selected=prefix==='source'?S.sourceId:prefix==='timeline'?S.timelineId:S.discussionId;select.innerHTML='<option value=>选择对象</option>'+opts([...new Map([...(prefix==='source'?model().funds:objectList(mode)),...found].map(x=>[x.id,x])).values()].map(x=>[x.id,x.name+' · '+x.code]),selected);}
