async function boot(){
 const [p,e,c,a,f,anchors,reference,industry,market,marketEvidence,feeData]=await Promise.all([get('data/v07/portfolio.json'),Promise.resolve({events:[]}),get('data/catalog.json'),get('data/analytics.json',EMPTY_ANALYTICS),get('data/v08/forum.json',{records:[],metrics:[]}),get('data/v08/evidence.json',{sources:[]}),get('data/v08/reference.json',{stocks:[]}),get('data/v09/industry.json',{records:[]}),get('data/v09/market-daily.json',{boards:[],valuations:[]}),get('data/v11/market.json',{calendar:{dates:[]},indices:{series:{}}}),get('data/v13/fee-comparison.json',{indexes:{}})]);
 const review=await get('data/v13/source-review.json',{excluded:[]});D.excludedEvents=review.excluded;
 D.funds=p.funds;D.builtAt=p.builtAt;D.events=e.events||[];D.reference={...c,sources:[...c.sources,...anchors.sources]};D.analytics={...a,feeGroups:feeData.indexes,feesBuiltAt:feeData.builtAt,asOf:new Date(Date.now()-86400000).toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'}),calendar:marketEvidence.calendar.dates,indices:[...(a.indices||[]),...Object.values(marketEvidence.indices.series||{}).filter(x=>!(a.indices||[]).some(i=>i.id===x.id)).map(x=>({...x,verified:false,basis:'price-index-observation'}))]};D.forum=f;D.stocks=reference.stocks||[];D.industry=industry.records||[];D.market=market;D.reference.sources.push({id:'market-calendar',title:'沪深交易日观察日历',entities:[],cadence:'profile',publisher:'上证指数行情日期',url:marketEvidence.calendar.sourceUrl,summary:`${marketEvidence.calendar.from||''} 至 ${marketEvidence.calendar.to||''}，${marketEvidence.calendar.dates.length} 个有行情日期；来源为上证指数日K线。`,contentCoverage:'source-values'});for(const x of Object.values(marketEvidence.indices.series||{}))D.reference.sources.push({id:'market-index-'+x.id,title:x.name+'价格指数序列',entities:[],cadence:'profile',publisher:'东方财富指数行情',url:'https://quote.eastmoney.com/zs'+x.code+'.html',period:x.to,summary:`${x.from} 至 ${x.to}，${x.count} 个观测点；价格指数，不含分红再投资。`,contentCoverage:'source-values',indexObservation:x});
 try{S.account={...normalizeAmounts(S.account.items||[]),savedAt:S.account.savedAt};}catch{S.account={items:[]};toast('持仓读取失败，原数据已保留');}
 library=createLibrary({dialog,close,toast,render,showNotebook:()=>{location.hash='library';render();},isNotebook:()=>S.view==='library'});
 document.addEventListener('click',e=>onClick(e).catch(err=>toast(err.message)));document.addEventListener('submit',onSubmit);document.addEventListener('change',onChange);document.addEventListener('input',onInput);
 window.addEventListener('hashchange',route);window.addEventListener('resize',()=>graph?.fit());route();refreshPublicStreams().catch(()=>{});loadAccountObjects();get('api/ai/status',{sharedAvailable:false}).then(status=>{S.sharedAvailable=status.sharedAvailable;if(S.view==='settings')render();});
}
async function refreshPublicStreams(){const [coverage,market]=await Promise.all([loadPublicData('v10/coverage.json',await get('data/v10/coverage.json',null)),loadPublicData('v09/market-daily.json',null)]);if(coverage)D.eventUpdatedAt=[D.eventUpdatedAt,coverage.news?.lastCheckedAt].filter(Boolean).sort().at(-1)||null;if(market)D.market=market;if(['news','analysis'].includes(S.view)&&!$('#v7-dialog').open&&!/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName||''))render();}
async function get(path,fallback){try{const r=await fetch('./'+path);if(!r.ok)throw Error(path);return await r.json();}catch(e){if(fallback!==undefined)return fallback;throw e;}}
function route(){const aliases={records:'holdings',timeline:'news',notebook:'library'};let v=location.hash.slice(1)||'holdings';S.view=aliases[v]||v;if(!NAV.some(n=>n[0]===S.view))S.view='holdings';S.selected.clear();render();window.scrollTo({top:0});}
function render(){
 D.events=D.events.filter(e=>!(D.excludedEvents||[]).some(x=>x.sourceRecordId===e.sourceRecordId||x.url===e.url));
 $('#v7-nav').innerHTML=NAV.map(([id,name])=>`<a href="#${id}" class="${S.view===id?'on':''}">${h(name)}</a>`).join('');
 $('#v7-crumb').innerHTML=`<strong>${h(NAV.find(n=>n[0]===S.view)[1])}</strong>`;
 const views={holdings:viewHoldings,analysis:viewAnalysis,news:viewTimeline,sources:viewSources,discussion:viewDiscussion,library:()=>'<h1 class="v7-h1">我的资料库</h1>'+library.notebookView(),settings:viewSettings};
 $('#v7-view').innerHTML=S.accountLoading&&['holdings','analysis','news','sources','discussion'].includes(S.view)?'<section class="v7-card">正在读取持仓资料…</section>':views[S.view]();$('#v7-foot').innerHTML='';$('#v7-pickbar').innerHTML='';graph=null;
 if(S.view==='holdings'&&model().funds.length&&$('#relationship-map')){graph=createGraph($('#relationship-map'),{details:showDetail,focus:id=>{S.focus=id;showDetail(id);const b=$('#graph-focus-label');if(b)b.textContent=id==='portfolio'?'':model().funds.find(f=>f.id===id)?.name||model().companies.find(c=>c.id===id)?.name||'';}});graph.update(model(),S.focus);paintInspector();}
 if(['news','sources','discussion','library'].includes(S.view)&&!S.accountLoading){const title=$('#v7-view h1'),anchor=title?.parentElement.classList.contains('v8-sectionhead')?title.parentElement:title;anchor?.insertAdjacentHTML('afterend',aiPanel());}
 library.afterRender();
}
function viewHoldings(){const m=model();return `<div class="v8-pagehead"><h1>我的持仓</h1>${btn('edit-holdings',m.funds.length?'管理持仓':'添加持仓','','v7-btn primary')}</div>
 <section class="v7-card holdings-summary"><div><span>持有总额</span><strong>${cash(m.total)}</strong></div><div><span>基金</span><strong>${m.funds.length}<small>只</small></strong></div><div class="holding-strip">${m.funds.slice(0,5).map(f=>`<button data-act="inspect" data-id="${h(f.id)}"><span>${h(f.name)}</span><strong>${pct(f.share)}</strong></button>`).join('')}${m.funds.length>5?btn('edit-holdings','全部 '+m.funds.length+' 只'):''}</div></section>
 ${m.funds.length?`<section class="v8-map-layout"><div class="v7-card v8-map-card"><div class="v8-sectionhead"><h2>关联图谱</h2><div class="v7-actions">${btn('graph-home','组合')}<span id="graph-focus-label">${h(m.funds.find(f=>f.id===S.focus)?.name||'')}</span>${btn('graph-minus','−')}${btn('graph-plus','＋')}${btn('graph-fit','适应')}</div></div><div id="relationship-map"></div></div><aside class="v7-card v8-inspector" id="v8-inspector" aria-label="对象详情"></aside></section>`:`<div class="v8-start"><span class="v8-start-icon">＋</span><h2>添加基金持仓</h2>${btn('edit-holdings','搜索基金并填写金额','','v7-btn primary')}</div>`}`;}
async function showDetail(id){S.detail=id;paintInspector();if(innerWidth<1000)$('#v8-inspector').scrollIntoView({behavior:'smooth',block:'start'});if(id!=='portfolio')try{await ensureObject(id);if(S.detail===id)paintInspector();}catch{}}
function paintInspector(all=false){const m=model(),f=m.funds.find(f=>f.id===S.detail),c=m.companies.find(c=>c.id===S.detail);let html;
 if(f){const old=D.reference.funds.find(x=>x.code===f.code),profile=f.profile;html=`<span class="v8-eyebrow">基金 · ${h(f.code)}</span><h2>${h(f.name)}</h2><form id="inline-holding-form" class="v8-inline-form" data-code="${h(f.code)}"><label>持有金额（元）<input name="amount" type="number" min="0.01" step="0.01" value="${f.amount}" required></label><button class="v7-btn primary">保存</button>${btn('delete-direct','删除',f.code)}</form><small>${pct(f.share)} · 占组合</small><dl class="v8-properties"><dt>基金类型</dt><dd>${h(f.type)}</dd><dt>管理人</dt><dd>${h(f.manager||'—')}</dd><dt>经理资料</dt><dd>${h(profile?.managerTenures?.map(x=>x.name+' · '+x.startDate).join(' / ')||(Array.isArray(profile?.managers)?profile.managers.map(x=>x.name||x).join('、'):profile?.managers)||old?.managerName||'—')}</dd><dt>跟踪指数</dt><dd>${h(f.indexName||'—')}</dd><dt>托管人</dt><dd>${h(profile?.custodian||'—')}</dd><dt>成立日期</dt><dd>${h(profile?.establishedAt||'—')}</dd><dt>管理费／托管费（来源值）</dt><dd>${feeLabel(profile?.fees?.management)} ／ ${feeLabel(profile?.fees?.custody)}</dd><dt>持仓报告日</dt><dd>${h(f.disclosure?.asOf||'—')} · ${f.disclosure?.complete?'完整披露':'已披露 '+f.holdings.length+' 只'}</dd></dl><div class="v7-actions">${ext('https://fund.eastmoney.com/'+f.code+'.html','基金档案')}${ext('https://fundf10.eastmoney.com/jjjz_'+f.code+'.html','净值')}${ext('https://guba.eastmoney.com/list,of'+f.code+'.html','基金吧')}</div>${reportPicker(f)}${navPreview(f)}${heldFundsMarkup(f)}${f.profile?.referencedTarget?.targetCode?`<div class="v7-actions">${btn('target-reference','目标ETF参考（规则推断）',f.profile.referencedTarget.targetCode,'v7-link')}</div>`:''}<div class="v7-actions">${btn('go-source','相关资料',f.id,'v7-link')}${btn('go-timeline','事件时间轴',f.id,'v7-link')}</div><h3>关联股票 <small>${f.holdings.length}</small></h3>${btn('all-related',all?'收起':'查看全部',f.id)}<div class="v8-related-list">${[...f.holdings].sort((a,b)=>b.weight-a.weight).slice(0,all?500:10).map(r=>`<button data-act="inspect" data-id="stock${h(r.code)}"><span>${h(r.name)}</span><small>${pct(r.weight)}</small><span>↗</span></button>`).join('')||`<p class="v8-muted">${h(holdingStatusText(f))}</p>`}</div>`;
 }else if(c){const stock=D.stocks.find(x=>x.code===c.code);html=`<span class="v8-eyebrow">股票 · ${h(c.code)}</span><h2>${h(c.name)}</h2><div class="v8-detail-value">${pct(c.share)}<small>占组合</small></div><dl class="v8-properties"><dt>公司全称</dt><dd>${h(stock?.fullName||'—')}</dd><dt>交易所</dt><dd>${h(({SSE:'上交所',SZSE:'深交所',BSE:'北交所',BJSE:'北交所'})[stock?.exchange]||'—')}</dd><dt>行业</dt><dd>${h(stock?.industry||'—')}</dd><dt>上市日期</dt><dd>${h(stock?.listingDate||stock?.listingMonth||'—')}</dd></dl><h3>持有路径</h3><div class="v8-related-list">${c.paths.map(p=>`<button data-act="inspect" data-id="${h(p.fundId)}"><span>${h(p.name)}</span><small>${pct(p.weight)}</small><span>↗</span></button>`).join('')}</div><div class="v7-actions">${ext('https://guba.eastmoney.com/list,'+c.code+'.html','股吧')}${btn('go-timeline','事件时间轴',c.id,'v7-link')}${btn('go-source','相关依据',c.id,'v7-link')}</div><small class="v8-muted">${h([...new Set(c.paths.map(p=>p.asOf).filter(Boolean))].join(' / '))}</small>`;
 }else html=`<span class="v8-eyebrow">组合</span><h2>持仓概览</h2><div class="v8-detail-value">${cash(m.total)}</div><dl class="v8-properties"><dt>基金</dt><dd>${m.funds.length} 只</dd><dt>持仓日期</dt><dd>${h(S.account.savedAt?new Date(S.account.savedAt).toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'}):today())}</dd></dl><div class="v8-related-list">${m.funds.map(f=>`<button data-act="inspect" data-id="${h(f.id)}"><span>${h(f.name)}</span><small>${pct(f.share)}</small><span>↗</span></button>`).join('')}</div>`;
 $('#v8-inspector').innerHTML=html+(S.detail.startsWith('fund')&&objectCards.has(S.detail)?'<details><summary>基金基础信息</summary>'+profileMarkup(objectCards.get(S.detail))+'</details>':'');if(all)$('#v8-inspector').dataset.all='1';else delete $('#v8-inspector').dataset.all;}
function editHoldings(){editingRows=structuredClone(S.account.items||[]);showHoldingEditor();}
function showHoldingEditor(){dialog('管理持仓',`<form id="holding-form"><div class="v8-fund-search"><input id="holding-search" aria-label="搜索要添加的基金" type="search" placeholder="基金代码或名称" autocomplete="off"><div id="holding-results"></div></div><div class="v8-holding-edit"><div class="v8-edit-header"><span>基金</span><span>当前持有金额（元）</span><span></span></div>${editingRows.map((r,i)=>`<div class="v8-edit-row"><div><strong>${h(r.name)}</strong><small>${h(r.code)}</small></div><input type="number" min="0.01" step="0.01" aria-label="${h(r.name)}持有金额" data-amount-index="${i}" value="${h(r.amount??'')}" required>${btn('remove-holding','×',String(i),'v7-x')}</div>`).join('')}</div><div class="v8-editor-footer"><span>合计 <strong id="editor-total">${cash(editingRows.reduce((s,r)=>s+(Number(r.amount)||0),0))}</strong></span><button class="v7-btn primary" type="submit">保存持仓</button></div></form>`);}
async function ensureL1(){return L1||(L1=await get('data/v07/funds-l1.json'));}
async function search(q,target){const token=++loadingSearch;if(!q.trim()){target.innerHTML='';return;}const list=await ensureL1();if(token!==loadingSearch||!target.isConnected)return;const hits=list.filter(r=>r[0].includes(q)||r[1].toLowerCase().includes(q.toLowerCase())).slice(0,12);target.innerHTML=hits.map(r=>btn('add-fund',`${h(r[1])}<small>${h(r[0])} · ${h(r[2])}</small>`,r[0],'v8-search-result')).join('')||'<span class="v8-muted">未找到基金</span>';}
const metric=(name,value)=>`<div class="v8-metric"><span>${name}</span><strong>${value??'—'}</strong></div>`;
const formula=text=>`<details class="v8-formula"><summary>公式</summary><p>${h(text)}</p></details>`;
function viewAnalysis(){const m=model();if(!m.funds.length)return `<h1 class="v7-h1">持仓分析</h1><div class="v8-start">${btn('edit-holdings','添加持仓','','v7-btn primary')}</div>`;return renderAnalysisV3(m,S.bounds,D.analytics,S.analysis,S.goal);}
function objectList(mode){const m=model(),held=mode==='fund'?m.funds:m.companies;const extra=S.view==='discussion'?D.discussionOptions[mode]:D.timelineOptions[mode];return [...new Map([...held,...extra].map(x=>[x.id,x])).values()];}
function objectModel(id){return selectionModel(model(),D.funds,id);}
function timelineModel(){return objectModel(S.timelineId);}
async function searchTimeline(input){return searchObjects(input,'timeline',S.timelineMode);}
function selector(mode,id,searchText,prefix){const list=objectList(mode).filter(x=>[x.name,x.code].join(' ').toLowerCase().includes(searchText.toLowerCase()));return `<div class="v8-object-picker"><input aria-label="搜索${prefix==='timeline'?'时间轴':'讨论'}对象" data-${prefix}-search value="${h(searchText)}" placeholder="搜索基金或股票"><select aria-label="选择${prefix==='timeline'?'时间轴':'讨论'}对象" data-${prefix}-object><option value="">选择${mode==='fund'?'基金':'公司'}</option>${opts(list.map(x=>[x.id,x.name+' · '+x.code]),id)}</select></div>`;}
function viewTimeline(){const m=timelineModel(),id=S.timelineId;const allEvents=id?eventSelection(D.events,m,S.timelineMode,id,today(),S.older):portfolioEvents(D.events,model(),S.timelineMode,today(),S.older);S.newsPage=Math.min(S.newsPage,Math.max(0,Math.ceil(allEvents.length/50)-1));const events=allEvents.slice(S.newsPage*50,(S.newsPage+1)*50);return `<div class="v8-sectionhead"><h1 class="v7-h1">事件时间轴</h1>${D.eventUpdatedAt?`<small class="v8-muted">资料更新 ${h(String(D.eventUpdatedAt).slice(0,10))}</small>`:''}</div><div class="v8-tabs">${btn('timeline-mode','按基金','fund',S.timelineMode==='fund'?'on':'')}${btn('timeline-mode','按公司','company',S.timelineMode==='company'?'on':'')}</div>${selector(S.timelineMode,id,S.timelineSearch,'timeline')}${id?`<div class="v7-actions">${btn('object-profile','基础信息',id)}</div>`:''}
 ${(id||model().funds.length)?`<div class="v8-sectionhead"><span class="v8-muted">${id?'所选对象':'我的持仓'} · ${S.older?'全部事件':'近30天'}</span></div><ol class="v7-timeline">${events.map(e=>`<li><time>${h(e.date)} · ${h(e.source)}${e.topics?.length?' · '+h(e.topics.map(t=>t.label).join(' / ')):''}</time><p class="v13-entities">${eventLabels(e)}</p><h4>${h(e.title)}</h4>${e.summary?`<p>${h(e.summary)}</p>`:''}${e.analysis?.points?.length?`<details><summary>AI 整理</summary>${e.analysis.points.map(p=>`<p>${h(p.text)}</p>`).join('')}</details>`:''}<div class="v7-actions">${ext(e.url,'原文')}${btn('collect-event','收藏',e.id,'v7-link')}<label><input type="checkbox" data-event-pick="${h(e.id)}" ${S.selected.has(e.id)?'checked':''}>选择</label></div></li>`).join('')||`<li class="v8-muted">${S.activityLoading===id?'正在读取…':'暂未收录'}</li>`}</ol>${allEvents.length>50?`<div class="v7-actions">${S.newsPage?btn('news-page','上一页','-1'):''}<span>${S.newsPage+1} / ${Math.ceil(allEvents.length/50)}</span>${(S.newsPage+1)*50<allEvents.length?btn('news-page','下一页','1'):''}</div>`:''}${events.length?`<button class="v7-btn" data-act="ai-summary" ${S.selected.size?'':'disabled'}>摘要所选事件</button>`:''}`:''}`;}
function portfolioIds(m=model()){return new Set([...m.funds,...m.companies].map(x=>x.id));}
function portfolioEvents(events,m,mode,day,older=false){return [...new Map((mode==='fund'?m.funds:m.companies).flatMap(x=>eventSelection(events,m,mode,x.id,day,older)).map(x=>[x.id,x])).values()].sort((a,b)=>b.date.localeCompare(a.date)||a.id.localeCompare(b.id));}
function sourceRows(objectId=S.sourceId){const obj=objectId;return sortSources(allSourceRows().filter(s=>s.visibility!=='internal'&&(sourceCadence(s)!=='news'||s.kind==='disclosure')&&(obj?s.entities.some(id=>id===obj||'stock'+D.reference.nodes.find(n=>n.id===id)?.code===obj):!model().funds.length||s.entities.some(id=>portfolioIds().has(id)||portfolioIds().has('stock'+D.reference.nodes.find(n=>n.id===id)?.code)))&&[s.title,s.publisher,s.summary,s.period].join(' ').toLowerCase().includes(S.sourceQuery.toLowerCase())));}
async function selectSource(id){S.sourceId=id;S.sourcePage=0;S.sourceLoading=id;render();try{if(id){await ensureObject(id);if(S.sourceId===id&&S.view==='sources')render();await loadActivity(id);}}catch{toast('资料读取失败，请重试');}finally{if(S.sourceId===id){S.sourceLoading='';if(S.view==='sources')render();}}}
function viewSources(){const m=model(),list=sourceRows();S.sourcePage=Math.min(S.sourcePage,Math.max(0,Math.ceil(list.length/50)-1));const rows=list.slice(S.sourcePage*50,(S.sourcePage+1)*50);return `<h1 class="v7-h1">公共资料库</h1><div class="v8-object-picker"><input aria-label="搜索基金或股票资料" id="source-object-query" placeholder="基金、股票名称或代码"><input aria-label="搜索依据" id="source-query" placeholder="搜索持仓、净值、报告或公告" value="${h(S.sourceQuery)}"><select aria-label="资料关联对象" id="source-object"><option value="">${m.funds.length?'我的持仓':'全部对象'}</option>${opts([...new Map([...m.funds,...m.companies,...D.sourceOptions,...(objectCards.has(S.sourceId)?[objectCards.get(S.sourceId)]:[])].map(x=>[x.id,x])).values()].map(x=>[x.id,x.name+' · '+x.code]),S.sourceId)}</select></div><div class="v8-evidence-tabs"><span>基础信息 · 持仓 · 净值 · 报告与公告</span>${btn('source-qa','问答')}</div>${profileMarkup(objectCards.get(S.sourceId))}<section class="v7-card"><small class="v8-muted">${list.length} 份资料</small><table class="v7-table"><thead><tr><th>资料</th><th>日期</th><th>来源</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr><td>${btn('source-detail',h(s.title),s.id,'v7-link')}</td><td>${h(s.publishedAt||s.period||'日期未提供')}</td><td>${h(s.publisher)}</td><td><label><input type="checkbox" data-source-pick="${h(s.id)}" ${S.selected.has(s.id)?'checked':''}>选择</label>${btn('collect-source','收藏',s.id,'v7-link')}</td></tr>`).join('')}</tbody></table>${list.length?'':`<p class="v8-muted">${S.sourceLoading?'正在读取…':'暂未收录'}</p>`}${list.length>50?`<div class="v7-actions">${S.sourcePage?btn('source-page','上一页','-1'):''}<span>${S.sourcePage+1} / ${Math.ceil(list.length/50)}</span>${(S.sourcePage+1)*50<list.length?btn('source-page','下一页','1'):''}</div>`:''}</section>`;}
function showSource(id){const s=allSourceRows().find(s=>s.id===id);if(!s)return;const table=s.holdings?`<small class="v8-muted">占基金净资产 · ${s.complete?'完整披露':'已收录部分'}</small><table class="v7-table"><thead><tr><th>股票</th><th>代码</th><th>占比</th></tr></thead><tbody>${[...s.holdings].sort((a,b)=>(b.weightPercent??-1)-(a.weightPercent??-1)).map(r=>`<tr><td>${h(r.name)}</td><td>${h(r.code)}</td><td>${Number.isFinite(r.weightPercent)?pct(r.weightPercent):'来源占比待核'}</td></tr>`).join('')}</tbody></table>`:'';const observation=s.navObservation;dialog(s.title,`<p class="v8-muted">${h(s.publisher)} · ${h(s.publishedAt||s.period||'')}</p>${s.summary?`<p>${h(s.summary)}</p>`:''}${table}${observation?navTable(observation):''}${s.indexObservation?`<details><summary>最近60条行情</summary><table class="v7-table"><thead><tr><th>日期</th><th>指数点位</th></tr></thead><tbody>${s.indexObservation.points.slice(-60).reverse().map(p=>`<tr><td>${h(p[0])}</td><td>${h(p[1])}</td></tr>`).join('')}</tbody></table></details>`:''}${s.contentCoverage==='link-only'?'<small class="v8-muted">已收录公告索引，正文见原文。</small>':''}${s.dataPoints?.length?`<table class="v7-table"><tbody>${s.dataPoints.map(p=>`<tr><td>${h(p.label)}</td><td>${h(p.value)}</td><td>${h(p.period)}</td></tr>`).join('')}</tbody></table>`:''}<p class="v8-muted">${h((s.locator||'').replace(/[（(]零基页号[^）)]*[）)]/g,''))}</p><div class="v7-actions">${ext(s.url,s.contentCoverage==='inferred-reference'?'目标ETF档案':'原文')}${btn('collect-source','收藏',s.id)}${sourceHighlights(s).length&&s.contentCoverage!=='link-only'?btn('source-summary','摘要',s.id):''}</div>`);}
function reportPicker(f){return f.periods?.length?`<label class="v7-field"><span>持仓报告日</span><select aria-label="持仓报告日" data-report-fund="${h(f.code)}">${f.periods.map(p=>`<option value="${h(p.asOf)}" ${p.asOf===f.disclosure?.asOf?'selected':''}>${h(p.asOf)} · ${p.holdings.length} 只${p.complete?' · 完整披露':''}</option>`).join('')}</select></label>`:'';}
function feeLabel(x){return h(typeof x==='string'?x:Number.isFinite(x?.annualDecimal)?(x.annualDecimal*100).toFixed(2)+'%':Number.isFinite(x?.rawPercentValue)?x.rawPercentValue+'%':'—');}
function navPreview(f){const n=f?.observations?.snapshot;return n&&!/货币/.test(f.type||'')&&Number.isFinite(n.nav)?`<dl class="v8-properties"><dt>单位净值（币种见资料）</dt><dd>${n.nav} · ${h(n.date)}</dd></dl>`:'';}
function navTable(observation){const points=observation.history?.points||[],n=observation.snapshot;return `${n?`<p>来源净值日期 ${h(n.date)} · 原始值 ${h(n.nav)} · 累计值 ${h(n.accNav)}</p>`:''}${points.length?`<p class="v8-muted">${h(points[0][0])} 至 ${h(points.at(-1)[0])} · ${points.length} 条 · 来源观察值</p><details><summary>最近60条记录</summary><table class="v7-table"><thead><tr><th>日期</th><th>来源值</th><th>累计值</th><th>日增长率（%）</th></tr></thead><tbody>${points.slice(-60).reverse().map(p=>`<tr>${p.map(v=>`<td>${h(v??'未提供')}</td>`).join('')}</tr>`).join('')}</tbody></table></details>`:''}<small class="v8-muted">分红、折算及货币基金字段未统一核验；未作为总回报使用。</small>`;}
const forumJobs=new Map();
function ensureForum(id){if(!id||id==='stock')return;if(!forumJobs.has(id))forumJobs.set(id,(async()=>{const {kind,code}=objectIdentity(id),path=`v12/posts/${kind}s/${code}.json`,data=await loadPublicData(path,await get('data/'+path,{schemaVersion:1,objectId:id,records:[]}));if(data.records?.length)D.forum.records=[...D.forum.records.filter(r=>r.objectId!==id),...data.records];if(S.view==='discussion')render();})());return forumJobs.get(id);}
const forumMaterials=postMaterials;
function viewDiscussion(){for(const id of S.discussionId&&S.discussionId!=='stock'?[S.discussionId]:portfolioIds()){ensureForum(id);loadCachedForum(id,S.forumDay);}const mode=S.discussionId.startsWith('stock')?'company':'fund',id=S.discussionId,m=objectModel(id),obj=[...m.funds,...m.companies,...objectCards.values()].find(x=>x.id===id),owned=portfolioIds(),rows=(D.forum.records||[]).filter(x=>x.date===S.forumDay&&(id?x.objectId===id:owned.has(x.objectId))).sort((a,b)=>b.date.localeCompare(a.date)||(b.publishedAt||'').localeCompare(a.publishedAt||'')).slice(0,30);return `<h1 class="v7-h1">帖子与评论</h1><div class="v8-tabs">${btn('discussion-mode','基金','fund',mode==='fund'?'on':'')}${btn('discussion-mode','公司','company',mode==='company'?'on':'')}</div>${selector(mode,id,S.discussionSearch,'discussion')}${obj?`<div class="v7-actions">${ext('https://guba.eastmoney.com/list,'+(mode==='fund'?'of':'')+obj.code+'.html','原始讨论区')}${btn('object-profile','基础信息',id)}</div>`:''}<div class="v7-actions"><label>日期 <input type="date" id="forum-date" value="${h(S.forumDay)}" max="${today()}"></label>${btn('forum-fetch','读取/继续读取帖子与评论')}${btn('forum-analyze','分析所选帖子')}${btn('forum-select-all','选择本页')}</div>${forumStatusMarkup(id)}${rows.map(r=>`<article class="v7-card"><small class="v8-muted">${h(r.date)} · ${h(r.source)} · ${h(objectCards.get(r.objectId)?.name||D.funds.find(f=>f.id===r.objectId)?.name||r.objectId)}${r.boardVerified?'':' · 关联待核'}${r.coverage?.body==='complete'?'':' · 正文待取得'}</small><h3>${h(r.title)}</h3>${r.content?`<details><summary>帖子正文</summary><p class="v11-post-text">${h(r.content)}</p></details>`:''}<details><summary>评论 · ${Array.isArray(r.comments)?'已取得 '+r.comments.length+(r.coverage?.comments==='complete'?'':' · 部分或待取得'):'正在读取'}</summary>${(r.comments||[]).map(c=>`<p><small>${h(c.at||'')}${c.replyTo?' · 回复':''}</small><br>${h(c.text)}</p>`).join('')}</details><div class="v7-actions">${ext(r.url,'原帖')}${btn('collect-forum','收藏帖子与评论',r.id,'v7-link')}<label><input type="checkbox" data-forum-pick="${h(r.id)}" ${S.forumSelected.has(r.id)?'checked':''}>选择</label></div></article>`).join('')||`<p class="v8-muted">${S.activityLoading?'正在读取…':'暂未取得帖子'}</p>`}<section class="v7-card"><h2>说法核对</h2><form id="verify-form"><label class="v7-field"><textarea name="claim" rows="3" placeholder="输入需要核对的具体说法" required maxlength="2000"></textarea></label><button class="v7-btn primary">核对</button></form></section>`;}

function viewSettings(){return `<h1 class="v7-h1">设置</h1><section class="v7-card"><h2>AI 服务</h2><form id="settings-form"><label class="v7-field"><span>使用方式</span><select name="mode">${opts([['shared','默认 AI'],['custom','自选 AI']],S.cfg.mode)}</select></label><p class="v8-muted">${S.sharedAvailable?'默认 AI 可用':'默认 AI 尚未配置'}</p><details ${S.cfg.mode==='custom'?'open':''}><summary>自选 AI 配置</summary><label class="v7-field"><span>接口地址</span><input name="url" type="url" value="${h(S.cfg.url)}" placeholder="API 站点或完整接口地址"></label><label class="v7-field"><span>API Key</span><input name="key" type="password" autocomplete="off" value="${h(S.cfg.key)}"></label><label class="v7-field"><span>模型名称</span><input name="model" value="${h(S.cfg.model)}"></label></details><button class="v7-btn primary">保存</button></form></section><section class="v7-card"><h2>持仓备份</h2><div class="v7-actions">${btn('export-account','导出持仓')}${btn('import-account','导入持仓')}<input id="account-file" type="file" accept="application/json" hidden></div></section>`;}

function evidenceMaterials(objectId=S.sourceId,question=''){
 const words=[...new Set((question.match(/[a-zA-Z0-9]{2,}|[\u4e00-\u9fff]{2,}/g)||[]).flatMap(w=>w.length>4?[w,...Array.from({length:w.length-1},(_,i)=>w.slice(i,i+2))]:[w]))];
 const sourceList=sourceRows(objectId).map(s=>({s,score:words.reduce((n,w)=>n+(s.title.includes(w)?1:0),0)+(s.holdings||s.navObservation?0.2:0)})).sort((a,b)=>b.score-a.score).slice(0,24).map(({s})=>({id:s.id,text:[s.title,s.publishedAt,s.period,s.locator,s.contentCoverage==='link-only'?'仅标题及原文入口，正文未读取':'',...sourceHighlights(s).map(i=>i.text),...(s.holdings||[]).map(r=>`${r.code} ${r.name}：${r.weightPercent===null?'占比待核':r.weightPercent+'%'}（占基金净资产）`),s.navObservation?'净值来源观察，尚未核为总回报；'+JSON.stringify(s.navObservation.snapshot||{}):''].filter(Boolean).join('\n'),url:safeUrl(s.url),date:s.publishedAt||s.period||null,locator:s.locator||''}));
 const recent=objectId?eventSelection(D.events,objectModel(objectId),objectId.startsWith('fund')?'fund':'company',objectId,today()).slice(0,6):[];
 return [...sourceList,...recent.map(e=>({id:e.id,text:[e.date,e.title,e.summary,e.contentCoverage==='title-only'?'仅标题，正文未读取':''].filter(Boolean).join(' '),url:safeUrl(e.url),date:e.date,locator:''}))];
}
async function runAI(task,materials,question=''){if(!materials.length&&task!=='verify')return toast('请选择资料');if(S.cfg.mode==='custom'&&(!S.cfg.url||!S.cfg.key||!S.cfg.model))return dialog('模型接口',`<div class="v7-actions">${btn('go-settings','前往设置','','v7-btn primary')}</div>`);dialog('处理中','<p class="v8-muted">正在生成…</p>');try{const result=await requestAI(S.cfg,task,materials,question);S.ai={result,materials,task};const labels={supported:'公开来源支持',contradicted:'与公开来源矛盾',unverifiable:'未找到足够依据'};dialog(result.title,`<span class="v8-eyebrow">模型生成${result.verdict?' · '+labels[result.verdict]:''}</span>${result.points.map(p=>`<p>${h(p.text)}</p><div class="v7-actions">${p.sourceIds.map(id=>{const s=materials.find(x=>x.id===id);return ext(s.url,(s.date||'来源')+(s.locator?' · '+s.locator:''));}).join('')}</div>`).join('')}<div class="v7-actions">${btn('collect-ai','收藏结果')}${btn('copy-ai','复制')}</div>`);}catch(e){dialog('未能生成结果',`<p>${h(e.name==='AbortError'?'请求超时':e.message)}</p>`);}}
async function onClick(e){if(e.target.closest('#v7-nav a[href="#holdings"],.v7-brand')){S.focus='portfolio';S.detail='portfolio';if(S.view==='holdings')render();}
 const el=e.target.closest('[data-act]');if(!el)return;const act=el.dataset.act,id=el.dataset.id;try{
 if(act==='clear-target'){if(put('zhijian-targets-v13',null)){S.goal=null;render();}return;}
 if(act==='delete-direct')return saveAccount(S.account.items.filter(r=>r.code!==id));
 if(act==='forum-fetch')return fetchForumNow();
 if(act==='close')return close();if(act==='edit-holdings')return editHoldings();
 if(act==='remove-holding'){syncEditor();editingRows.splice(Number(id),1);return showHoldingEditor();}
 if(act==='add-fund'){const row=(L1||[]).find(x=>x[0]===id);if(!row)return;$('#v7-q').value='';$('#v7-results').innerHTML='';if($('#holding-form')){syncEditor();if(!editingRows.some(r=>r.code===id))editingRows.push({code:id,name:row[1],type:row[2],amount:''});return showHoldingEditor();}addingFund=row;return dialog(row[1],`<form id="quick-add-form"><label class="v7-field"><span>当前持有金额（元）</span><input name="amount" type="number" min="0.01" step="0.01" value="${h(S.account.items.find(x=>x.code===id)?.amount??'')}" required autofocus></label><button class="v7-btn primary">保存持仓</button></form>`);}
 if(act==='target-reference'){const card=await ensureObject('fund'+id),target=D.funds.find(f=>f.code===id);return dialog('目标ETF参考',`<p class="v8-muted">${h(card.name)} · ${h(target?.disclosure?.asOf||'')} · 占目标ETF净资产；未计入联接基金的股票占比。</p><div class="v8-related-list">${(target?.holdings||[]).slice(0,10).map(r=>`<div><span>${h(r.name)}</span><strong>${pct(r.weight)}</strong></div>`).join('')}</div>${btn('go-source','查看目标ETF资料','fund'+id)}`);}if(act==='object-profile'){const card=await ensureObject(id);return dialog(card.name,profileMarkup(card)+(card.kind==='fund'?navPreview(D.funds.find(f=>f.id===id)):''));}if(act==='inspect')return showDetail(id);if(act==='all-related')return paintInspector(!$('#v8-inspector').dataset.all);
 if(act==='graph-home'){S.focus='portfolio';showDetail('portfolio');graph.update(model(),S.focus);$('#graph-focus-label').textContent='';return;}if(act==='graph-minus')return graph?.zoom(1/1.15);if(act==='graph-plus')return graph?.zoom(1.15);if(act==='graph-fit')return graph?.fit();
 if(act==='analysis-ai')return runAI('qa',[{id:'computed-factors',text:factorEvidenceV3(model(),S.bounds,D.analytics,S.goal),url:location.origin+'/#analysis',date:D.analytics.asOf||today()}],'解释已计算的指标、日期和限制。只使用给定数字，不重新计算，不给出总分、预测或买卖建议。');
 if(act==='analysis-tab'){S.analysis=id;return render();}
 if(act==='timeline-mode'){S.timelineMode=id;S.timelineId='';S.newsPage=0;S.timelineSearch='';S.selected.clear();return render();}if(act==='older'){S.older=!S.older;if(S.older&&!D.archivesLoaded){const index=await loadPublicData('archive/index.json',await get('data/archive/index.json',{months:[]}));const groups=await Promise.all(index.months.filter(x=>/^\d{4}-\d{2}$/.test(x)).map(async month=>loadPublicData('archive/'+month+'.json',await get('data/archive/'+month+'.json',{events:[]}))));D.archivedEvents=groups.flatMap(x=>x.events);D.events=[...new Map([...D.events,...D.archivedEvents].map(e=>[e.id,e])).values()];D.archivesLoaded=true;}return render();}
 if(act==='go-timeline'){S.timelineMode=id.startsWith('fund')?'fund':'company';S.timelineId=id;await loadObjectStreams(id);return location.hash='news';}
 if(act==='go-source'){if($('#v7-dialog').open)close();location.hash='sources';S.view='sources';return selectSource(id);}if(act==='source-detail')return showSource(id);
 if(act==='discussion-mode'){S.forumSelected.clear();S.discussionId=id==='fund'?'':'stock';return render();}
 if(act==='collect-event'){const ev=D.events.find(x=>x.id===id);return library.collect({title:ev.title,url:ev.url,excerpt:ev.summary||'',referenceId:'event:'+id});}
 if(act==='collect-source'){const s=allSourceRows().find(x=>x.id===id);return library.collect({title:s.title,url:s.url,excerpt:sourceHighlights(s).map(x=>x.text).join('\n\n'),referenceId:s.id});}
 if(act==='news-page'){S.newsPage=Math.max(0,S.newsPage+Number(id));return render();}if(act==='source-page'){S.sourcePage=Math.max(0,S.sourcePage+Number(id));return render();}if(act==='source-summary'){const s=allSourceRows().find(x=>x.id===id);if(s.contentCoverage==='link-only')return toast('请先打开原文');return runAI('summary',[{id:s.id,text:sourceHighlights(s).map(x=>x.text).join('\n'),url:s.url,date:s.publishedAt,locator:(s.locator||'').replace(/[（(]零基页号[^）)]*[）)]/g,'')}]);}
 if(act==='source-qa')return dialog('资料问答','<form id="qa-form"><label class="v7-field"><textarea name="question" placeholder="输入问题" rows="3" required></textarea></label><button class="v7-btn primary">提问</button></form>');
 if(act==='ai-summary')return runAI('summary',D.events.filter(x=>S.selected.has(x.id)).map(x=>({id:x.id,text:[x.date,x.title,x.summary].join(' '),url:x.url,date:x.date})));
 if(act==='forum-select-all'){for(const el of document.querySelectorAll('[data-forum-pick]')){el.checked=true;S.forumSelected.add(el.dataset.forumPick);}return;}
 if(act==='forum-analyze'){let selected=(D.forum.records||[]).filter(r=>S.forumSelected.has(r.id)).slice(0,30);await Promise.all(selected.map(r=>ensureForum(r.objectId)));selected=uniquePosts((D.forum.records||[]).filter(r=>S.forumSelected.has(r.id))).slice(0,30);if(selected.some(r=>!Array.isArray(r.comments)||!r.content&&!r.comments.length))return toast('部分所选帖子的正文尚未取得');return runAI('qa',forumMaterials(selected),'整理所选帖子及已取得评论中的主要说法；保留分歧，逐条引用原帖，不把网友判断当作已核实事实。');}
 if(act==='collect-forum'){const initial=D.forum.records.find(x=>x.id===id);await ensureForum(initial.objectId);const r=D.forum.records.find(x=>x.id===id&&x.objectId===initial.objectId),text=[r.title,r.content||'',...(r.comments||[]).map(c=>(c.at||'')+' '+c.text)].join('\n\n');return library.collect({title:r.title,url:r.url,excerpt:text.slice(0,20000),note:[r.date,r.coverage?.comments==='complete'?'':'评论为已取得部分',text.length>20000?'已保存前20000字，完整内容见原帖':''].filter(Boolean).join(' · '),referenceId:'forum:'+r.id});}
 if(act==='verify-claim'){const [oid,date,index]=id.split('|'),block=D.forum.claims.find(x=>x.objectId===oid&&x.date===date),claim=block?.claims?.[Number(index)];if(claim)return runAI('verify',evidenceMaterials(oid),claim.text);return;}
 if(act==='forum-verify'){const r=D.forum.records.find(x=>x.id===id);return runAI('verify',evidenceMaterials(S.discussionId),r.claim||r.title);}
 if(act==='collect-ai'){const ids=new Set(S.ai.result.points.flatMap(p=>p.sourceIds));const refs=S.ai.materials.filter(s=>ids.has(s.id));return library.collect({title:S.ai.result.title,excerpt:S.ai.result.points.map(p=>p.text).join('\n'),url:refs[0]?.url||'',note:'模型生成'+refs.map(s=>'\n'+(s.date||'')+' '+s.url).join(''),referenceId:'ai:'+crypto.randomUUID()});}
 if(act==='copy-ai')return navigator.clipboard.writeText(S.ai.result.points.map(p=>p.text).join('\n')).then(()=>toast('已复制'));
 if(act==='go-settings'){close();return location.hash='settings';}
 if(act==='export-account'){const blob=new Blob([JSON.stringify({format:'zhijian-holdings',...S.account},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='持仓.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(act==='import-account')return $('#account-file').click();
 }catch(err){toast(err.message);}}
function syncEditor(){for(const el of document.querySelectorAll('[data-amount-index]'))editingRows[Number(el.dataset.amountIndex)].amount=el.value;}
function saveAccount(rows){const value={...normalizeAmounts(rows),savedAt:new Date().toISOString()};if(put('zhijian-holdings-v08',value)){S.account=value;S.accountLoading=Boolean(value.items.length);S.focus='portfolio';S.detail='portfolio';S.timelineId='';close();render();loadAccountObjects();toast('持仓已保存');}}
async function onSubmit(e){const form=e.target,id=form.id;if(!['holding-form','quick-add-form','inline-holding-form','target-form','ai-workbench','scenario-form','bounds-form','settings-form','verify-form','qa-form'].includes(id))return;e.preventDefault();const data=Object.fromEntries(new FormData(form));if(e.submitter?.name)data[e.submitter.name]=e.submitter.value;try{
 if(id==='holding-form'){syncEditor();return saveAccount(editingRows);}
 if(id==='inline-holding-form')return saveAccount(S.account.items.map(r=>r.code===form.dataset.code?{...r,amount:data.amount}:r));
 if(id==='target-form'){const m=model(),weights=Object.fromEntries(Object.entries(data).map(([id,x])=>[id,Number(x)]));validateTargets(m,weights);const baseline={};for(const f of m.funds){const n=f.observations?.snapshot;if(n&&Number.isFinite(n.nav)&&n.nav>0)baseline[f.id]={amount:f.amount,nav:n.nav,date:n.date};}const goal={weights,baseline,savedAt:new Date().toISOString()};if(put('zhijian-targets-v13',goal)){S.goal=goal;render();toast('已保存目标与参考值');}return;}
 if(id==='ai-workbench')return pageAI(data);
 if(id==='quick-add-form'){const items=structuredClone(S.account.items),existing=items.find(x=>x.code===addingFund[0]);if(existing)existing.amount=data.amount;else items.push({code:addingFund[0],name:addingFund[1],type:addingFund[2],amount:data.amount});return saveAccount(items);}
 if(id==='settings-form'){if(put('zhijian-v07-cfg',data)){S.cfg=data;toast('已保存');}return;}
 if(id==='bounds-form'){const value={};for(const [k,v]of Object.entries(data)){value[k]=v===''?null:Number(v);if(value[k]!==null&&(!Number.isFinite(value[k])||value[k]<0||k==='loss'&&value[k]===0||['fund','company'].includes(k)&&value[k]>100||k==='horizon'&&(value[k]<1||value[k]>600)))throw Error('上限数值无效');}if(put('zhijian-boundaries-v08',value)){S.bounds=value;render();toast('已保存');}return;}
 if(id==='scenario-form'){const m=model(),shock=Number(data.shock);if(!Number.isFinite(shock)||shock< -100||shock>100)throw Error('涨跌幅须为−100%至100%');const share=data.scope==='all'?100:m.funds.find(f=>f.id===data.scope)?.share??m.companies.find(c=>c.id===data.scope)?.share;if(!Number.isFinite(share))throw Error('请选择对象');const amount=m.total*share/100*shock/100;$('#scenario-result').innerHTML=`<div class="v8-metrics">${metric('组合变化',pct(share*shock/100))}${metric('金额变化',cash(amount))}</div>${S.bounds.loss!==null?`<small>${Math.max(0,-amount)>S.bounds.loss?'超过损失关注金额':'未超过损失关注金额'}</small>`:''}`;return;}
 if(id==='verify-form')return runAI('verify',evidenceMaterials(S.discussionId,data.claim),String(data.claim).replace(/@\S+/g,'').trim());
 if(id==='qa-form'){await loadObjectStreams(S.sourceId);return runAI('qa',evidenceMaterials(S.sourceId,data.question),data.question);}
 }catch(err){toast(err.message);}}
async function onChange(e){const el=e.target;if(el.dataset.sourcePick){el.checked?S.selected.add(el.dataset.sourcePick):S.selected.delete(el.dataset.sourcePick);return;}if(el.id==='forum-date'){S.forumDay=el.value;S.forumSelected.clear();return render();}if(el.dataset.forumPick){el.checked?S.forumSelected.add(el.dataset.forumPick):S.forumSelected.delete(el.dataset.forumPick);return;}if(el.dataset.reportFund){const f=D.funds.find(f=>f.code===el.dataset.reportFund);Object.assign(f,await objectStore.relations(f.code,{asOf:el.value}));S.focus=f.id;S.detail=f.id;return render();}if(el.name==='mode'&&el.closest('#settings-form')){el.form.querySelector('details').open=el.value==='custom';return;}if(el.dataset.eventPick){el.checked?S.selected.add(el.dataset.eventPick):S.selected.delete(el.dataset.eventPick);const b=document.querySelector('[data-act="ai-summary"]');if(b)b.disabled=!S.selected.size;return;}
 if(el.matches('[data-timeline-object]')){const id=el.value;S.timelineId=id;S.newsPage=0;S.selected.clear();S.activityLoading=id;render();if(id)await loadObjectStreams(id);if(S.timelineId===id){S.activityLoading='';if(S.view==='news')render();}return;}if(el.matches('[data-discussion-object]')){const id=el.value;S.discussionId=id;S.forumSelected.clear();S.activityLoading=id;render();if(id)await loadObjectStreams(id);if(S.discussionId===id){S.activityLoading='';if(S.view==='discussion')render();}return;}
 if(el.id==='source-object')return selectSource(el.value);
 if(el.id==='account-file'&&el.files[0])try{const data=JSON.parse(await el.files[0].text());if(data.format!=='zhijian-holdings')throw Error('持仓文件格式无效');saveAccount(data.items);}catch(err){toast(err.message);}}
function onInput(e){const el=e.target;if(el.name==='question'&&el.closest('#ai-workbench'))S.aiQuestions[S.view]=el.value;if(el.id==='holding-search')search(el.value,$('#holding-results')).catch(err=>toast(err.message));if(el.id==='v7-q')search(el.value,$('#v7-results')).catch(err=>toast(err.message));
 if(el.dataset.amountIndex!==undefined){syncEditor();$('#editor-total').textContent=cash(editingRows.reduce((s,r)=>s+(Number(r.amount)||0),0));}
 if(el.matches('[data-timeline-search]')){S.timelineSearch=el.value;searchTimeline(el).catch(err=>toast(err.message));}
 if(el.matches('[data-discussion-search]')){S.discussionSearch=el.value;searchObjects(el,'discussion',S.discussionId.startsWith('stock')?'company':'fund').catch(err=>toast(err.message));}
 if(el.id==='source-object-query')searchObjects(el,'source',null).catch(err=>toast(err.message));
 if(el.id==='source-query'){S.sourceQuery=el.value;S.sourcePage=0;clearTimeout(onInput.t);onInput.t=setTimeout(()=>{const pos=el.selectionStart;render();$('#source-query').focus();$('#source-query').setSelectionRange(pos,pos);},250);}
 if(el.closest('#scenario-form')&&$('#scenario-result'))$('#scenario-result').innerHTML='';}


function holdingStatusText(f){return ({'via-target-etf':'本基金未披露直接股票，可查看目标ETF参考。','holds-funds':'来源列示持有基金，见上方明细。','source-missing':'公开来源暂缺股票明细。','no-stock-by-design':'当前分类与来源表未列示股票。','pending-retry':'当前尚未取得本基金或目标ETF的股票明细。'})[f.holdingStatus]||'来源未列示股票明细。';}
function heldFundsMarkup(f){const x=f.profile?.holdingExtra;if(!x?.heldFunds?.length)return '';return `<h3>持有基金</h3><small>来源表列值 · 报告日期未提供</small><div class="v8-related-list">${x.heldFunds.map(r=>`<button data-act="object-profile" data-id="fund${h(r.fundCode)}"><span>${h(r.fundName)}</span><small>${pct(r.weight)}</small><span>↗</span></button>`).join('')}</div>`;}
function eventLabels(e){return [...new Map((e.entities||[]).map(x=>[x.kind+'|'+x.code,x])).values()].map(x=>{const id=x.kind+x.code;const name=x.name||objectCards.get(id)?.name||D.funds.find(f=>f.id===id)?.name||D.stocks.find(s=>s.code===x.code)?.name||x.code;const label=({fund:'基金',stock:'股票',company:'企业',market:'市场',unassigned:'待归属'})[x.kind]||'关联对象';return `<span>${h(label)} · ${h(name)} ${h(x.code)}</span>`;}).join(' ');}

function aiPanel(){return `<section class="v7-card v13-ai" aria-label="AI分析"><h2>AI分析</h2><form id="ai-workbench"><div class="v7-actions"><button class="v7-btn" name="preset" value="summary">摘要</button><button class="v7-btn" name="preset" value="impact">与我的持仓有何关联</button><button class="v7-btn" name="preset" value="differences">要点与分歧</button>${S.view==='sources'?'<button class="v7-btn" name="preset" value="search">辅助查询</button>':''}</div><label class="v7-field"><span>自写问题或要求</span><textarea name="question" rows="2" maxlength="4000" placeholder="输入问题，也可直接使用上方选项">${h(S.aiQuestions[S.view]||'')}</textarea></label><button class="v7-btn primary" name="preset" value="custom">开始分析</button><small>${S.view==='library'?'仅发送勾选收藏中的文字。':'勾选材料可限定分析范围；未勾选时使用当前对象或持仓的已收录材料。'}</small></form></section>`;}
function fitMaterials(rows){const unique=[...new Map(rows.map(x=>[x.id,x])).values()].slice(0,30),per=Math.min(28000,Math.floor(110000/Math.max(1,unique.length)));return unique.map(x=>{let text=String(x.text||'');const bytes=new TextEncoder();if(bytes.encode(text).length>per){let lo=0,hi=text.length;while(lo<hi){const mid=Math.ceil((lo+hi)/2);if(bytes.encode(text.slice(0,mid)).length<=per-100)lo=mid;else hi=mid-1;}text=text.slice(0,lo)+'\n[材料已节选，剩余内容未发送]';}return {...x,text};});}
async function pageAI(data){
 const preset=data.preset||'custom',questions={summary:'概括材料中的事实、关键数字和日期；注明仅标题或节选的限制。',impact:'说明材料与已给持仓路径的关联、可能需要关注的事实和不确定性；不预测涨跌或给出交易建议。',differences:'整理主要说法与分歧，区分原始事实、网友判断和待核事项。',search:'根据问题查找所给资料中的相关依据，列出已找到和未找到的信息。'};let materials=[];
 if(S.view==='library')materials=library.analysisMaterials();
 if(S.view==='news'){const events=S.selected.size?D.events.filter(x=>S.selected.has(x.id)):S.timelineId?eventSelection(D.events,timelineModel(),S.timelineMode,S.timelineId,today(),S.older):portfolioEvents(D.events,model(),S.timelineMode,today(),S.older);materials=events.slice(0,29).map(x=>({id:x.id,text:[x.date,x.title,x.summary,eventLabels(x).replace(/<[^>]*>/g,''),x.contentCoverage==='title-only'?'仅标题，未读取正文':''].join('\n'),url:x.url,date:x.date}));}
 if(S.view==='sources'){
  const question=(data.question||'').trim();if(preset==='search'&&question){const hits=await objectStore.search(question,null,5);await Promise.allSettled(hits.map(x=>ensureObject(x.id)));if(!hits.length){const objects=await objectStore.objects();const explicit=objects.filter(x=>question.includes(x.code)||x.name.length>2&&question.includes(x.name)).slice(0,5);await Promise.allSettled(explicit.map(x=>ensureObject(x.id)));materials=explicit.flatMap(x=>evidenceMaterials(x.id,question));}else materials=hits.flatMap(x=>evidenceMaterials(x.id,question));}
  if(!materials.length)materials=evidenceMaterials(S.sourceId,data.question||'');if(S.selected.size)materials=materials.filter(x=>S.selected.has(x.id));
 }
 if(S.view==='discussion'){const ids=S.discussionId&&S.discussionId!=='stock'?[S.discussionId]:[...portfolioIds()];await Promise.all(ids.map(ensureForum));const posts=uniquePosts(D.forum.records.filter(r=>r.date===S.forumDay&&ids.includes(r.objectId)&&(!S.forumSelected.size||S.forumSelected.has(r.id)))).slice(0,29);materials=forumMaterials(posts);}
 if(!materials.length)return toast(S.view==='library'?'请勾选要分析的收藏文字':'当前没有可分析材料，请选择对象或先读取资料');
 if(preset==='custom'&&!String(data.question||'').trim())return toast('请输入问题或选择上方选项');
 if(preset==='impact'){const m=model();materials=materials.slice(0,29);materials.push({id:'portfolio-context',text:'当前输入金额折算的资金占比（不含金额）：\n'+m.funds.map(f=>`${f.name} ${f.code}：${pct(f.share)}；报告日 ${f.disclosure?.asOf||'缺失'}；关联股票 ${f.holdings.slice(0,20).map(r=>`${r.name} ${r.code}（占基金净资产${pct(r.weight)}）`).join('、')}`).join('\n'),url:null,date:today()});}
 return runAI(preset==='summary'?'summary':'qa',fitMaterials(materials),[questions[preset]||'',data.question||''].filter(Boolean).join('\n'));
}
function loadCachedForum(id,day){const k=id+'|'+day;if(localForumJobs.has(k))return;localForumJobs.set(k,(async()=>{try{const res=await fetch('/api/forum?objectId='+encodeURIComponent(id)+'&date='+day);if(!res.ok)return;const data=await res.json();localForumStatus.set(k,data);if(data.records?.length)D.forum.records=mergePosts(D.forum.records,data.records);if(S.view==='discussion'&&S.forumDay===day)render();}catch{}})());}
function forumStatusMarkup(id){const data=localForumStatus.get(id+'|'+S.forumDay);if(!id||id==='stock'||!data)return '';const label={queued:'已加入读取队列',running:'正在读取正文与评论…',partial:'已有内容已保留；仍有页面或评论未取全，可继续读取。',complete:data.records?.length?'当前取得的帖子正文与评论已读取。':'所选公开来源未列示该日帖子。','not-collected':'尚未进行按需读取。'}[data.status]||'';return `<p class="v8-muted" role="status">${h(label)}</p>`;}
async function fetchForumNow(){const id=S.discussionId,day=S.forumDay;if(!/^(fund|stock)[0-9A-Z]{1,12}$/.test(id))return toast('请先选择基金或股票');S.activityLoading=id;render();try{const r=await fetch('/api/forum',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({objectId:id,date:day})});const d=await r.json();if(!r.ok)throw Error(d.error||'当前服务不支持按需读取');toast('已加入读取队列，可稍后继续读取');const poll=async(n=0)=>{const res=await fetch('/api/forum?objectId='+encodeURIComponent(id)+'&date='+day);const x=await res.json();localForumStatus.set(id+'|'+day,x);if(x.records){D.forum.records=mergePosts(D.forum.records,x.records);if(S.view==='discussion')render();}if(['queued','running'].includes(x.status)&&n<45)setTimeout(()=>poll(n+1).catch(()=>{}),3000);else{S.activityLoading='';toast(x.status==='complete'?'读取完成':x.message||'已保留取得的内容，可再次继续读取');if(S.view==='discussion')render();}};await poll();}catch(e){S.activityLoading='';toast(e.message);}}

boot().catch(err=>{$('#v7-view').innerHTML='<div class="v7-empty">页面未能加载，请刷新重试。</div>';console.error(err);});
